/* ---------------------------------------------------------------------------
   Der SAP-Bericht vom 27.08.2026, Periode 7
   ---------------------------------------------------------------------------
   sap_struktur traegt den Bilanz-/GuV-Bericht als Momentaufnahme.  Der Stand
   in der Datenbank war aelter und hatte noch den Auffangtopf 0080000000, in
   dem echte Aufwandskonten lagen; sein Ergebnis der gewoehnlichen
   Geschaeftstaetigkeit lautete -90.659,26 statt -302.345,84.

   Geladen wird sonst mit scripts/sap-struktur-laden.py aus der XLSX.  Auf
   dem Server fehlt openpyxl, deshalb kommt derselbe Inhalt hier als SQL -
   erzeugt aus der Tabelle, die das Skript oertlich geschrieben hat.

   Das ist kein festgeschriebenes Ergebnis, sondern der Bericht selbst: die
   Vergleichsgroesse, gegen die gerechnet wird.
--------------------------------------------------------------------------- */

DELETE FROM controlling.sap_struktur WHERE jahr = 2026 AND periode = 7;
